        return [start]  # If start and goal are the same, we're done.

    # Initialize the stack for the recursive (by default) stack implementation
    stack = [(start, [start])]
    visited = set()

    # Perform DFS to find the path
    while stack:
        (current, path) = stack.pop()
        visited.add(current)

        # If current node is the goal, we found the path
        if current == goal:
            return path
        # Explore only unvisited neighbors
