def find_path(graph, start, goal, explored=None, path=None):
    if path is None:
        path = [start]
    if explored is None:
        explored = set()

    if start == goal:
        return path

    if not path[-1] in graph:  # If the last node in the path is not in the graph, we can't move further.
        return None

    for node in graph[path[-1]]:
        if node not in explored:
            new_path = find_path(graph, node, goal, explored | {node}, path + [node])
