def find_path(graph, start, goal):
    if start is None or goal is None:
        raise ValueError("Both start and goal should have a valid non-empty name.")

    if start not in graph:
        raise ValueError(f"Start node ({start}) is not in the graph.")

    if goal not in graph:
        raise ValueError(f"Goal node ({goal}) is not in the graph.")

    def dfs(visited, current, goal, path):
        visited.add(current)
        path.append(current)
        if current == goal:
            return path
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                result = dfs(visited.copy(), neighbor, goal, path.copy())
                if result:
                    return result
        path.pop()
        return None

    path = []
    visited = set()
    path = dfs(visited, start, goal, path)
    return path if path else None
