    # A simple implementation using a recursive (non-optimised) path finder
    if start == goal:
        return [start]  # If start and goal are the same, we found a trivial path

    visited = set() # A set to keep track of visited nodes to avoid loops
    path = [start]  # The list to return the path in
    stack = [(start, [start])]  # Stack for DFS, tuple of current node and path

    while stack:
        (current, current_path) = stack.pop()
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            return current_path
        for neighbor in graph[current]:
            if neighbor not in visited:
                stack.append((neighbor, current_path + [neighbor]))
    return None
