def find_path(graph, start, goal):
    # If the start and goal are the same, we have a trivial path (the start itself)
    if start == goal:
        return [start]

    # If the graph is empty or the start and goal are not in the graph, we cannot have a path
    if not graph or start not in graph or goal not in graph:
        return None

    # Track visited nodes to avoid cycles
    visited = set()

    # Track the path from the start to the current node
    def search(node):
        if node == goal:
            return True
        if node in visited:
            return False
        visited.add(node)
        if node in graph:
            return any(search(neighbor) for neighbor in graph[node])
        return False

    # Start the search
    return search(start) and [goal] + path for path in set(search(start) and reversed(path) for path in search(start)) if path
