def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Stack for the recursive and then reverse the path to get the correct order
    stack = [(tuple([start]), start, [])]
    visited = set()

    # Use a stack instead of a queue for DFS
    while stack:
        (path, node, path_from_start) = stack.pop()
        visited.add(node)

        if node == goal:
            # Reverse the path to get it in the correct order
            return path_from_start + [node]

        for neighbor in graph[node]:
            if neighbor not in visited:
                stack.append((path + (neighbor,), neighbor, path_from_start + [node]))

    # If we've exhausted the graph without finding a path to the goal
