def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the recursive (non-recursive) path search
    def dfs_search(stack, visited, parent):
        if stack:
            node = stack.pop()
            if node == goal:
                return visited, parent
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = node
                    stack.append(neighbor)
            return dfs_search(stack, visited, parent)
        return None, None

    visited = set()
    parent = {node: None for node in graph}
    stack = [start]
    visited.add(start)

    result, parent = dfs_search(stack, visited, parent)
    if result is None:
        return None
    else:
        path = []
        while result != start:
            path.append(result)
            result = parent[result]
        path.append(start)
        path.reverse()
        return path
