def find_path(graph, start, goal):
    # A stack for the recursive and a set for the closed (visited) nodes
    stack = [(start, [start])]

    # Recursive function for the path search
    def search(x, path):
        # If the x is the goal, return the path
        if x == goal:
            return path
        # Mark x as visited (closed)
        graph[x].remove(x)  # Remove the edge from the graph to avoid cycles
        closed = set([x])
        # Iterate over neighbors
        for y in graph[x]:
            if y not in closed:
                path_y = search(y, path + [y])
                if path_y is not None:
                    return path_y
        return None

    while stack:
        x, path = stack.pop()
        if x == goal:
            return path
        stack.extend([(y, path + [y]) for y in graph[x] if y not in closed])

    return None
