def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the recursive and non-recursive (if using) stack usage
    def dfs(graph, start, goal, path, closed):
        if start == goal:
            return path
        for neighbor in graph[start]:
            if neighbor not in closed:
                new_path = dfs(graph, neighbor, goal, path + [neighbor], closed + [neighbor])
                if new_path:
                    return new_path
        return None

    # Try to find a path using DFS
    path = dfs(graph, start, goal, [start], [start])

    # If path is not found, try BFS
    if path is None:
        from collections import deque
        queue = deque([(start, [start])])
        visited = set([start])

        while queue:
            current, path = queue.popleft()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    if neighbor == goal:
                        return path + [neighbor]
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))

    return path
