def find_path(graph, start, goal):
    # A simple recursive path finding by backtracking. If we reach a dead end,
    # we backtrack through the recursion stack
    if start == goal:
        return [start]  # If we are at our goal, we found a path

    visited = set()  # Visited nodes to avoid cycles

    def recursive_search(node):
        if node in visited:
            return None  # We have reached a dead end
        visited.add(node)
        if node == goal:
            return [goal]  # We have reached our goal, return the path
        for neighbor in graph[node]:
            path = recursive_search(neighbor)
            if path:
                return [node] + path  # Path found, combine current node with the neighbor's path

    return recursive_search(start)
