def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    if start == goal:
        return [start]

    # Initialize the stack for the recursive and recursive non-recursive (by using a stack) - you can choose either
    def dfs(graph, start, goal, path):
        if start == goal:
            return path + [start]
        for neighbor in graph[start]:
            if neighbor not in path:
                new_path = dfs(graph, neighbor, goal, path + [start])
                if new_path:
                    return new_path
        return None

    def bfs(graph, start, goal):
        # Initialize the queue for BFS
        queue = [(start, [start])]
        while queue:
            (node, path) = queue.pop(0)
            if node == goal:
                return path + [node]
            for neighbor in graph[node]:
                if neighbor not in path:
                    queue.append((neighbor, path + [node]))
        return None

    # Implement a recursive DFS and BFS to find the path
    dfs_path = dfs(graph, start, goal, [])
    bfs_path = bfs(graph, start, goal)

    if dfs_path:
        return dfs_path
    elif bfs_path:
        return bfs_path
    else:
        return None

